function(container, apiUrl, tables) {
  // 業務ロジックモジュールをインポート
  const { 
    collectSalesData, 
    classifySalesDataByProduct, 
    classifySalesDataByStore, 
    filterValidProductData, 
    collectWeatherData, 
    collectEventData, 
    collectSeasonalData, 
    analyzeCorrelationSalesWeather, 
    analyzeCorrelationSalesEvent, 
    analyzeCorrelationSalesSeason, 
    compareWithHistoricalData, 
    findAlternativeComparisonData, 
    validateComparisonPeriod 
  } = window.aivicLogic || {};

  let currentProducts = [];
  let selectedOrders = [];

  // テーブルインデックス
  const STORES_TABLE = 1; // 店舗マスタ
  const PRODUCTS_TABLE = 2; // 商品マスタ
  const DEMAND_FORECAST_TABLE = 8; // 需要予測結果
  const ORDER_TABLE = 9; // 発注データ

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    if (errorDiv) {
      errorDiv.textContent = message;
      errorDiv.classList.remove('hidden');
      setTimeout(() => errorDiv.classList.add('hidden'), 5000);
    }
    window.aivicNotify?.error(message);
  }

  // 成功表示関数
  function showSuccess(message) {
    window.aivicNotify?.success(message);
  }

  // 日付バリデーション
  function validateDateRange() {
    const startDate = container.querySelector('#date-start')?.value;
    const endDate = container.querySelector('#date-end')?.value;

    if (startDate && endDate && startDate > endDate) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }

    // 業務ロジックでの期間バリデーション
    if (validateComparisonPeriod && startDate && endDate) {
      try {
        const isValid = validateComparisonPeriod(startDate, endDate);
        if (!isValid) {
          showError('指定された期間は無効です');
          return false;
        }
      } catch (error) {
        showError('期間バリデーションエラー: ' + error.message);
        return false;
      }
    }

    return true;
  }

  // 需要予測データを取得・分析
  async function getDemandForecast(productId, storeId, startDate, endDate) {
    try {
      // 売上データを収集
      const salesData = collectSalesData ? await collectSalesData(productId, storeId, startDate, endDate) : [];

      // 商品別に分類
      const productSalesData = classifySalesDataByProduct ? classifySalesDataByProduct(salesData) : salesData;

      // 有効な商品データをフィルタリング
      const validProductData = filterValidProductData ? filterValidProductData(productSalesData) : productSalesData;

      // 天候データを収集
      const weatherData = collectWeatherData ? await collectWeatherData(startDate, endDate) : [];

      // イベントデータを収集
      const eventData = collectEventData ? await collectEventData(startDate, endDate) : [];

      // 季節データを収集
      const seasonalData = collectSeasonalData ? collectSeasonalData(startDate, endDate) : [];

      // 相関分析
      let correlationResults = {};
      if (analyzeCorrelationSalesWeather) {
        correlationResults.weather = analyzeCorrelationSalesWeather(validProductData, weatherData);
      }
      if (analyzeCorrelationSalesEvent) {
        correlationResults.event = analyzeCorrelationSalesEvent(validProductData, eventData);
      }
      if (analyzeCorrelationSalesSeason) {
        correlationResults.seasonal = analyzeCorrelationSalesSeason(validProductData, seasonalData);
      }

      // 過去データとの比較
      const historicalComparison = compareWithHistoricalData ? 
        await compareWithHistoricalData(validProductData, startDate, endDate) : null;

      return {
        salesData: validProductData,
        weatherData,
        eventData,
        seasonalData,
        correlationResults,
        historicalComparison
      };
    } catch (error) {
      console.error('需要予測データ取得エラー:', error);
      throw error;
    }
  }

  // 発注データを読み込み
  async function loadOrderData() {
    try {
      const startDate = container.querySelector('#date-start')?.value;
      const endDate = container.querySelector('#date-end')?.value;
      const storeId = container.querySelector('#store-select')?.value;

      if (!validateDateRange()) return;

      // 発注データを取得
      const orderData = await window.aivicApi.list(tables[ORDER_TABLE], {
        startDate,
        endDate,
        storeId
      });

      // 需要予測データを取得
      const forecastData = await window.aivicApi.list(tables[DEMAND_FORECAST_TABLE], {
        startDate,
        endDate,
        storeId
      });

      // テーブルに表示
      displayOrderData(orderData, forecastData);

      showSuccess('発注データを読み込みました');
    } catch (error) {
      showError('発注データの読み込みに失敗しました: ' + error.message);
    }
  }

  // 発注データをテーブルに表示
  function displayOrderData(orderData, forecastData) {
    const tbody = container.querySelector('#order-table tbody');
    if (!tbody) return;

    tbody.innerHTML = '';

    orderData.forEach(order => {
      const forecast = forecastData.find(f => f.productId === order.productId);
      const row = document.createElement('tr');

      row.innerHTML = `
        <td><input type="checkbox" class="order-checkbox" data-order-id="${order.id}"></td>
        <td>${order.productName || ''}</td>
        <td>${order.currentStock || 0}</td>
        <td>${forecast?.predictedDemand || 0}</td>
        <td><input type="number" class="order-quantity" value="${order.orderQuantity || 0}" min="0"></td>
        <td>${order.supplierName || ''}</td>
        <td>${order.orderDate || ''}</td>
        <td>
          <select class="order-status">
            <option value="pending" ${order.status === 'pending' ? 'selected' : ''}>未発注</option>
            <option value="ordered" ${order.status === 'ordered' ? 'selected' : ''}>発注済</option>
            <option value="delivered" ${order.status === 'delivered' ? 'selected' : ''}>納品済</option>
          </select>
        </td>
      `;

      tbody.appendChild(row);
    });

    currentProducts = orderData;
  }

  // 自動発注計算
  async function calculateAutoOrder() {
    try {
      const startDate = container.querySelector('#date-start')?.value;
      const endDate = container.querySelector('#date-end')?.value;
      const storeId = container.querySelector('#store-select')?.value;

      if (!validateDateRange()) return;

      // 商品データを取得
      const products = await window.aivicApi.list(tables[PRODUCTS_TABLE]);

      const autoOrders = [];

      for (const product of products) {
        try {
          // 需要予測データを取得・分析
          const forecastResult = await getDemandForecast(product.id, storeId, startDate, endDate);

          // 現在の在庫を取得
          const currentStock = product.currentStock || 0;
          const predictedDemand = forecastResult.correlationResults?.weather?.predictedValue || 
                                 forecastResult.salesData?.averageSales || 0;

          // 安全在庫を考慮した発注量計算
          const safetyStock = product.safetyStock || Math.ceil(predictedDemand * 0.2);
          const orderQuantity = Math.max(0, predictedDemand + safetyStock - currentStock);

          if (orderQuantity > 0) {
            autoOrders.push({
              productId: product.id,
              productName: product.name,
              currentStock,
              predictedDemand: Math.ceil(predictedDemand),
              orderQuantity: Math.ceil(orderQuantity),
              supplierName: product.supplierName || '',
              orderDate: new Date().toISOString().split('T')[0],
              status: 'pending'
            });
          }
        } catch (error) {
          console.error(`商品 ${product.name} の自動発注計算エラー:`, error);
        }
      }

      // 結果をテーブルに表示
      displayOrderData(autoOrders, []);

      showSuccess(`${autoOrders.length}件の自動発注を計算しました`);
    } catch (error) {
      showError('自動発注計算に失敗しました: ' + error.message);
    }
  }

  // 発注データを保存
  async function saveOrderData() {
    try {
      const rows = container.querySelectorAll('#order-table tbody tr');
      const orders = [];

      rows.forEach(row => {
        const checkbox = row.querySelector('.order-checkbox');
        if (checkbox?.checked) {
          const orderId = checkbox.dataset.orderId;
          const quantity = row.querySelector('.order-quantity')?.value;
          const status = row.querySelector('.order-status')?.value;

          if (quantity && parseFloat(quantity) > 0) {
            orders.push({
              id: orderId || null,
              productId: row.cells[1].textContent,
              orderQuantity: parseFloat(quantity),
              status: status,
              orderDate: new Date().toISOString().split('T')[0]
            });
          }
        }
      });

      if (orders.length === 0) {
        showError('保存する発注データを選択してください');
        return;
      }

      // 発注データを保存
      for (const order of orders) {
        if (order.id) {
          await window.aivicApi.update(tables[ORDER_TABLE], order.id, order);
        } else {
          await window.aivicApi.save(tables[ORDER_TABLE], order);
        }
      }

      showSuccess(`${orders.length}件の発注データを保存しました`);

      // データを再読み込み
      await loadOrderData();
    } catch (error) {
      showError('発注データの保存に失敗しました: ' + error.message);
    }
  }

  // 選択された発注を削除
  async function deleteSelectedOrders() {
    try {
      const checkboxes = container.querySelectorAll('.order-checkbox:checked');

      if (checkboxes.length === 0) {
        showError('削除する発注データを選択してください');
        return;
      }

      if (!confirm(`${checkboxes.length}件の発注データを削除しますか？`)) {
        return;
      }

      for (const checkbox of checkboxes) {
        const orderId = checkbox.dataset.orderId;
        if (orderId) {
          await window.aivicApi.delete(tables[ORDER_TABLE], orderId);
        }
      }

      showSuccess(`${checkboxes.length}件の発注データを削除しました`);

      // データを再読み込み
      await loadOrderData();
    } catch (error) {
      showError('発注データの削除に失敗しました: ' + error.message);
    }
  }

  // 店舗選択肢を読み込み
  async function loadStoreOptions() {
    try {
      const stores = await window.aivicApi.list(tables[STORES_TABLE]);
      const storeSelect = container.querySelector('#store-select');

      if (storeSelect) {
        storeSelect.innerHTML = '<option value="">全店舗</option>';
        stores.forEach(store => {
          const option = document.createElement('option');
          option.value = store.id;
          option.textContent = store.name;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      showError('店舗データの読み込みに失敗しました: ' + error.message);
    }
  }

  // 全選択/全解除
  function toggleAllOrders() {
    const masterCheckbox = container.querySelector('#select-all-orders');
    const checkboxes = container.querySelectorAll('.order-checkbox');

    checkboxes.forEach(checkbox => {
      checkbox.checked = masterCheckbox?.checked || false;
    });
  }

  // イベントリスナーを設定
  function setupEventListeners() {
    // 検索ボタン
    const searchBtn = container.querySelector('#search-orders-btn');
    if (searchBtn) {
      searchBtn.addEventListener('click', loadOrderData);
    }

    // 自動発注計算ボタン
    const autoOrderBtn = container.querySelector('#auto-order-btn');
    if (autoOrderBtn) {
      autoOrderBtn.addEventListener('click', calculateAutoOrder);
    }

    // 保存ボタン
    const saveBtn = container.querySelector('#save-orders-btn');
    if (saveBtn) {
      saveBtn.addEventListener('click', saveOrderData);
    }

    // 削除ボタン
    const deleteBtn = container.querySelector('#delete-orders-btn');
    if (deleteBtn) {
      deleteBtn.addEventListener('click', deleteSelectedOrders);
    }

    // 全選択チェックボックス
    const selectAllCheckbox = container.querySelector('#select-all-orders');
    if (selectAllCheckbox) {
      selectAllCheckbox.addEventListener('change', toggleAllOrders);
    }

    // 日付入力のバリデーション
    const dateInputs = container.querySelectorAll('#date-start, #date-end');
    dateInputs.forEach(input => {
      input.addEventListener('change', validateDateRange);
    });
  }

  // 初期化処理
  async function initialize() {
    try {
      await loadStoreOptions();
      setupEventListeners();

      // デフォルトの日付を設定
      const today = new Date();
      const startDate = new Date(today.getFullYear(), today.getMonth(), 1);
      const endDate = new Date(today.getFullYear(), today.getMonth() + 1, 0);

      const startInput = container.querySelector('#date-start');
      const endInput = container.querySelector('#date-end');

      if (startInput) startInput.value = startDate.toISOString().split('T')[0];
      if (endInput) endInput.value = endDate.toISOString().split('T')[0];

      // 初期データを読み込み
      await loadOrderData();
    } catch (error) {
      showError('初期化に失敗しました: ' + error.message);
    }
  }

  // 初期化実行
  initialize();
}
